def main():
    coverage = json.loads((AUDIT / 'FOCUSED_SPELL_SOURCE_PREPARATION_COVERAGE.json').read_text(encoding='utf-8'))
    assert len(coverage['cohortFiles']) == 15 and coverage['distinctPreparedPendingSpellIds'] == 232
    prior = coverage['cohortFiles'] + [x + '_SOURCE_PREPARATION.json' for x in ['TRANSMUTATION_RANK5','ABJURATION_RANK5','CONJURATION_RANK5','DIVINATION_RANK5']]
    prepare(
        prefix='UNIVERSAL_RANK5', title='Remaining rank-five Universal source audit', questions=QUESTIONS,
        selector=lambda r: r['operational'] is None and 'Universal' in r['schools'] and r['id'] != 'planar-binding' and min(v['rank'] for v in r['classAccess'].values()) == 5,
        expected_count=7, question_prefix='UN5', prior_files=prior, expected_prior_count=264,
        counterpart_ids=['dispel-magic','counterspell','resonance-anchor','faction-portal',
                         'mist-step','resonance-bridge','message','faction-insight','speak-with-dead'],
        pending_ids=['greater-dispel','antimagic-field-lesser','passwall','spell-theft'],
        deferred_ids=['planar-gate'], expected_alias_ids=['concordant-mindlink'],
        extra_excerpts={
            'CONTROL_STATES_PLAYTEST.md':['Root, physical restraints and suppression'],
            'CREATURE_LIFECYCLE_PLAYTEST.md':['At the table','Stats and ownership'],
            'EQUIPMENT_ACQUISITION_PLAYTEST.md':['Object damage and Sunder'],
            'CHARACTER_FOUNDATION_TABLES.md':None,
        },
        introduction='Seven remaining Universal identities retain six mechanical questions and Planar Gate as an unchanged post-push receipt. Planar Binding is already preserved with both placements in the Conjuration cohort and is not duplicated. Concordant Mindlink retains its only possible historical Core alias without an automatic merge. Quicken Cast,Spell Seal and permanent Teleportation Circle keep their strong printed promises and need precise bounded operational decisions.',
        future_dispatch='Prepared only while Mining/shared gathering source review is active. Rebase current dependencies before the six-spell mechanical conference,including exact local teleport and information boundaries. Planar Gate remains excluded until the authorized push and verified remote commit. Source decisions precede authored cards and separate exact review.')


if __name__ == '__main__':
    main()
